"""Independent golden traces from the immutable baseline, not generated by either runtime."""
def request(xml, maximum=2048, failure=-1, filtering=0, stop=0, actions="f,f,f,c,f"):
    return f"X {xml.hex() or '-'} {maximum} {failure} {filtering} {stop} {actions}\n"


def stepped(xml, events, *, filtering=0):
    # For these small documents: exactly one raw read, one data feed, empty final.
    return (request(xml, filtering=filtering),
            f"O Ok 0 1\nR 0 {len(xml)} {len(xml)}\n" + events +
            f"F Ok {len(xml)} 0 1\nF Ok {len(xml)} 1 1\n"
            f"F Unsupported {len(xml)} 1 1\nC {len(xml)}\nF Unsupported {len(xml)} 0 0\nEND\n")


VECTORS = [
    stepped(b'<r a="v">x</r>', "S 72 61 76\nT 78\nE 72\n"),
    stepped(b'<p:r xmlns:p="urn:x"/>', "S 703a72 786d6c6e733a70 75726e3a78\nE 703a72\n"),
    stepped('<r>é</r>'.encode(), "S 72\nT c3a9\nE 72\n"),
    stepped(b'<r>&amp;</r>', "S 72\nT 26\nE 72\n"),
    (request(b'<r></s>', actions="f,c"),
     "O Ok 0 1\nR 0 7 7\nS 72\nF ParseError 0 0 1\nC 0\nEND\n"),
    (request(b'', actions="f,c"),
     "O Ok 0 1\nF ParseError 0 0 1\nC 0\nEND\n"),
    (request(b'<r/>', failure=0, actions="f,c"),
     "O Ok 0 1\nR 0 4 -1\nF IoError 0 0 1\nC 0\nEND\n"),
    (request(b'<r/>', maximum=1, actions="f,f,f,f,f"),
     "O Ok 0 1\nR 0 4 1\nF Ok 1 0 1\nR 1 3 1\nF Ok 2 0 1\n"
     "R 2 2 1\nF Ok 3 0 1\nR 3 1 1\nS 72\nE 72\nF Ok 4 0 1\nF Ok 4 1 1\nEND\n"),
    (request(b'<r/>', stop=1, actions="p"), "P Ok\nEND\n"),
    (request(b'<r>x</r>trailing', stop=2, actions="p"),
     # Stop is observed between chunks: trailing junk in the SAME feed still fails.
     "R 0 16 16\nS 72\nT 78\nE 72\nP ParseError\nEND\n"),
    (request(b'<r>&nbsp;</r>', filtering=1, actions="f,f"),
     "O Ok 0 1\nR 0 13 13\nS 72\nT c2a0\nE 72\nF Ok 9 0 1\nF Ok 9 1 1\nEND\n"),
]


# Stepped mode must ignore an already-stopped handler.
VECTORS.append((request(b'<r/>', stop=1, actions="f,f"),
    "O Ok 0 1\nR 0 4 4\nS 72\nE 72\nF Ok 4 0 1\nF Ok 4 1 1\nEND\n"))
